// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }
    function testFuzz_property(bytes32 assertionId, bytes32 identifier, uint256 time, bytes calldata ancillaryData, address caller) public {
        vm.assume(caller != address(this) && caller != address(0));

        c.assertionDisputedCallback(assertionId);

        vm.prank(caller);
        bool reverted = false;
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assertTrue(reverted);
    }
}
